P = [
 dict(pmid='43061936', doi='10.1002/jat.70514', journal='J Appl Toxicol', title='Exposure to Diesel Particulate Matter Aggravates Developmental Toxicity Induced by Cyclophosphamide in Rats.', tier='C', basis='Lab / research instrument', short='Rat co-exposure: diesel particulate matter aggravates cyclophosphamide-induced fetal abnormalities and delayed ossification, not uniformly dose-dependent', design='Animal exposure study', pm='Diesel particulate matter administered to pregnant rats alongside cyclophosphamide; doses not stated in the abstract', geo='Korea (laboratory)', endpoint='Embryo-fetal development; maternal hepatic oxidative-stress markers (MDA, CAT, SOD)', affil='Chonnam National University, Republic of Korea; Chonnam National University, Republic of Korea', n='Pregnant rats received cyclophosphamide with or without concomitant diesel particulate matter; endpoints were maternal toxicity, fetal weight, morphological alterations and ossification, plus hepatic malondialdehyde and catalase and superoxide-dismutase activities. Cyclophosphamide alone reduced maternal and gravid uterine weight, fetal and placental weight and hepatic antioxidant activity. Added diesel PM aggravated several fetal abnormalities and ossification delay and further lowered maternal catalase and SOD, though responses were not uniformly dose-dependent. No CIs are reported. Weakness: a co-exposure design with a potent chemotherapeutic cannot isolate a PM effect size, non-monotonic responses suggest few animals per dose, and the administration route is not stated. Relevance: none to monitoring; it is an interaction-screening result.', sub=corpus.REPR),
 dict(pmid='', doi='10.1016/j.envpol.2026.129583', journal='Environmental Pollution', title='Lysosome-associated oxidative signals and membrane permeabilization contribute to intracellular ROS accumulation and alveolar epithelial cell death induced by zinc oxide nanoparticles', tier='C', basis='Lab / research instrument', short='Zinc oxide nanoparticles kill alveolar epithelial cells through lysosomal lipid peroxidation and membrane permeabilization; NRF2 is protective', design='Animal exposure study + in vitro', pm='Zinc oxide nanoparticles by oropharyngeal aspiration in mice and in alveolar epithelial cells; doses not stated in the abstract', geo='China (laboratory)', endpoint='Alveolar epithelial cell death, lysosomal membrane permeabilization and oxidative stress', affil='not stated; not stated', n='Oropharyngeal aspiration of ZnO nanoparticles raised pulmonary 4-hydroxynonenal and activated NRF2 in mice, with greater injury and lysosomal change in the alveolar than the bronchial compartment. In vitro, uptake was clathrin- and cholesterol-dependent with lysosomal trafficking; the particles increased lysosomal lipid peroxidation, altered CALPAIN1 and mature CTSB/CTSD and permeabilized lysosomal membranes. N-acetylcysteine and a CTSB inhibitor attenuated injury, while Nrf2 silencing worsened it. No exposure-response or CIs are reported. Weakness: engineered-nanoparticle doses are not anchored to ambient or occupational concentrations, and the comparison across lung compartments is qualitative. Relevance: metal-oxide ultrafines are invisible to optical mass sensors; the relevant exposure metric here is surface area or number.', sub=corpus.MECH),
 dict(pmid='43064501', doi='10.1136/bmjophth-2026-003077', journal='BMJ Open Ophthalmol', title='Relationship between PM2.5 exposure during wildfires and acute angle-closure: a self-controlled case series.', tier='C', basis='Not stated', short='Wildfire PM2.5 and acute angle-closure, self-controlled case series (metadata only)', design='Metadata only: no abstract in Crossref at issue time', pm='Wildfire-period PM2.5 (per title); exposure source not stated', geo='USA (California)', endpoint='Acute angle-closure episodes (per title)', affil='Stanford Medicine, USA; Byers Eye Institute, Stanford, USA', n='Metadata only. The title indicates a self-controlled case series relating PM2.5 exposure during wildfires to acute angle-closure (BMJ Open Ophthalmology, Stanford). No abstract reached the index at issue time, so no finding is asserted. Relevance: a self-controlled design needs daily exposure at the patient address, which during fires varies over kilometres and hours - the regime where regulatory monitors are sparsest and sensor networks or smoke models carry the exposure. Priority recheck when indexed.', sub=corpus.OTHR),
 dict(pmid='43062604', doi='10.1007/s10661-026-16165-5', journal='Environ Monit Assess', title='Atmospheric polycyclic aromatic hydrocarbon emissions, multimedia fate, and human health risk assessment in Punjab Province, Pakistan (2015-2024): a bottom-up emission inventory approach.', tier='C', basis='Model (CTM / LUR / ML)', short='Punjab, Pakistan bottom-up PAH inventory 2015-2024: emissions up 32.8% to 5287 t/yr, domestic coal 53.1% of the total', design='Emission inventory', pm='Bottom-up inventory of 16 USEPA priority PAHs by source and fuel, Monte Carlo uncertainty (10,000 iterations); multimedia fate and health-risk assessment', geo='Pakistan (Punjab)', endpoint='PAH emissions, multimedia fate and human health risk', affil='not stated; not stated', n='First source-resolved bottom-up PAH emission inventory for Punjab Province, 2015-2024, built from official Pakistani activity statistics and compiled emission factors with Monte Carlo uncertainty propagation. Total PAH emissions rose from 3,981.5 t in 2015 to 5,287.3 t in 2024 (+32.8%), with no sign of the policy-driven inflection seen in comparable Chinese provinces; domestic coal combustion contributed 53.1% and petroleum combustion 25.7%. Weakness: emission factors are transferred from other countries to Pakistani fuels, stoves and kilns, activity data are provincial aggregates, and the multimedia fate and risk layers compound those uncertainties without validation against measured ambient PAH. Relevance: particle-bound PAH is a combustion-source marker no mass sensor resolves; an inventory of this kind is only testable against filter or online composition measurement.', sub=corpus.EXPO),
]
